// Payments on the user's non-deleted orders.
export function listPaymentsForUser(userId, callback) {
  orders.findByUser(userId)
    .then((rows) => payments.findByOrders(rows.map((o) => o.id)))
    .then((rows) => callback(null, rows), (err) => callback(err));
}

