import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, listPaymentsForUser, uncapturedTotalCents } from '../src/services/payment-service.js';
import { OrderRepository } from '../src/repositories/order-repository.js';
import { PaymentRepository } from '../src/repositories/payment-repository.js';
import { routes } from '../src/api/routes.js';

test('listPaymentsForUser returns payments on that user orders only', (t, done) => {
  listPaymentsForUser(1, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows.map((p) => p.id), [100]);
    done();
  });
});

test('listPaymentsForUser returns an empty list for an unknown user', (t, done) => {
  listPaymentsForUser(999, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows, []);
    done();
  });
});

test('listPaymentsForUser reads through the repositories', (t, done) => {
  const findByUser = t.mock.method(OrderRepository.prototype, 'findByUser', () => Promise.resolve([{ id: 12 }]));
  const findByOrders = t.mock.method(PaymentRepository.prototype, 'findByOrders');
  listPaymentsForUser(1, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(findByUser.mock.calls[0].arguments, [1]);
    assert.deepEqual(findByOrders.mock.calls[0].arguments, [[12]]);
    assert.deepEqual(rows.map((p) => p.id), [101]);
    done();
  });
});

test('listPaymentsForUser passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(PaymentRepository.prototype, 'findByOrders', () => Promise.reject(boom));
  listPaymentsForUser(1, (err, rows) => {
    assert.equal(err, boom);
    assert.equal(rows, undefined);
    done();
  });
});

test('GET /users/:id/payments routes to listPaymentsForUser with a numeric id', (t, done) => {
  const route = routes.find((r) => r.method === 'GET' && r.path === '/users/:id/payments');
  assert.ok(route);
  route.handler({ params: { id: '2' } }, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows.map((p) => p.id), [101]);
    done();
  });
});

test('findPaymentsForOrder finds the payment for an order', (t, done) => {
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, null);
    assert.equal(rows.length, 1);
    assert.equal(rows[0].amount_cents, 4200);
    done();
  });
});

test('findPaymentsForOrder reads through PaymentRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findByOrder = t.mock.method(PaymentRepository.prototype, 'findByOrder', () => Promise.reject(boom));
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(findByOrder.mock.callCount(), 1);
    assert.deepEqual(findByOrder.mock.calls[0].arguments, [10]);
    assert.equal(err, boom);
    assert.equal(rows, undefined);
    done();
  });
});

test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
  uncapturedTotalCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 9900);
    done();
  });
});

test('uncapturedTotalCents reads through PaymentRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findUncaptured = t.mock.method(PaymentRepository.prototype, 'findUncaptured', () => Promise.reject(boom));
  uncapturedTotalCents((err, total) => {
    assert.equal(findUncaptured.mock.callCount(), 1);
    assert.equal(err, boom);
    assert.equal(total, undefined);
    done();
  });
});
